$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Drawing
$Root = (Get-Location).Path
$OutDir = Join-Path $Root 'docs/miyake-yuko/img/tiktok-assets/variants-10-korean'
$TokaDir = Join-Path $Root 'docs/miyake-yuko/img/8mobby-toka'
New-Item -ItemType Directory -Path $OutDir -Force | Out-Null
function MakeBrush($hex){ New-Object Drawing.SolidBrush ([Drawing.ColorTranslator]::FromHtml($hex)) }
function MakePen($hex,$w){ $p=New-Object Drawing.Pen ([Drawing.ColorTranslator]::FromHtml($hex)), $w; $p.StartCap='Round'; $p.EndCap='Round'; return $p }
function MakeFont($name,$size,$style='Regular'){ try { New-Object Drawing.Font($name,$size,[Drawing.FontStyle]::$style,[Drawing.GraphicsUnit]::Pixel) } catch { New-Object Drawing.Font('Yu Gothic UI',$size,[Drawing.FontStyle]::$style,[Drawing.GraphicsUnit]::Pixel) } }
function DrawRound($g,$x,$y,$w,$h,$r,$fill,$stroke=$null){ $path=New-Object Drawing.Drawing2D.GraphicsPath; $d=$r*2; $path.AddArc($x,$y,$d,$d,180,90); $path.AddArc($x+$w-$d,$y,$d,$d,270,90); $path.AddArc($x+$w-$d,$y+$h-$d,$d,$d,0,90); $path.AddArc($x,$y+$h-$d,$d,$d,90,90); $path.CloseFigure(); if($fill){$g.FillPath($fill,$path)}; if($stroke){$g.DrawPath($stroke,$path)}; $path.Dispose() }
function DrawText($g,$t,$f,$b,$x,$y,$w,$h,$a='Center'){ $sf=New-Object Drawing.StringFormat; $sf.Alignment=[Drawing.StringAlignment]::$a; $sf.LineAlignment='Center'; $sf.Trimming='EllipsisCharacter'; $g.DrawString($t,$f,$b,(New-Object Drawing.RectangleF $x,$y,$w,$h),$sf); $sf.Dispose() }
function DrawImg($g,$path,$x,$y,$w,$h,$rot=0){ $im=[Drawing.Image]::FromFile($path); $sc=[Math]::Min($w/$im.Width,$h/$im.Height); $dw=$im.Width*$sc; $dh=$im.Height*$sc; $state=$g.Save(); $g.TranslateTransform($x+$w/2,$y+$h/2); if($rot -ne 0){$g.RotateTransform($rot)}; $g.DrawImage($im,-$dw/2,-$dh/2,$dw,$dh); $g.Restore($state); $im.Dispose() }
function Header($g,$sub){ DrawText $g 'ビューティムード診断' $Title (MakeBrush '#e94778') 68 32 944 72; DrawText $g $sub $Sub (MakeBrush '#372626') 100 103 880 34 }
function Footer($g){ DrawRound $g 118 1415 844 45 22 (MakeBrush '#fffdfb') (MakePen '#f39bb5' 2); DrawText $g '答えをつなげて、あなたのビューティムードへ' $Foot (MakeBrush '#e94778') 132 1418 816 38 }
function Choice($g,$x,$y,$w,$h,$kana,$label,$color,$fill){ DrawRound $g $x $y $w $h 25 (MakeBrush $fill) (MakePen $color 3); DrawText $g $kana $Kana (MakeBrush $color) ($x+8) ($y+4) 62 ($h-8); DrawText $g $label $Label (MakeBrush $color) ($x+78) ($y+8) ($w-88) ($h-16) 'Near' }
function Question($g,$x,$y,$w,$h,$q,$txt,$color){ DrawRound $g $x $y $w $h 22 (MakeBrush '#ffffff') (MakePen $color 3); DrawText $g $q $QFont (MakeBrush $color) $x ($y+1) $w 30; DrawText $g $txt $Tiny (MakeBrush '#3b2929') ($x+8) ($y+30) ($w-16) ($h-34) }
function Pair($g,$y,$q,$qt,$a,$b,$c1,$c2){ Question $g 405 $y 270 76 $q $qt '#e94778'; Choice $g 88 ($y+100) 370 84 $a[0] $a[1] $c1 '#f8fffb'; Choice $g 622 ($y+100) 370 84 $b[0] $b[1] $c2 '#fff7fb' }
$Title=MakeFont 'HGP創英角ﾎﾟｯﾌﾟ体' 56 'Bold'; $Sub=MakeFont 'HG丸ｺﾞｼｯｸM-PRO' 23 'Bold'; $Kana=MakeFont 'HGP創英角ﾎﾟｯﾌﾟ体' 54 'Bold'; $Label=MakeFont 'HG丸ｺﾞｼｯｸM-PRO' 25 'Bold'; $Tiny=MakeFont 'HG丸ｺﾞｼｯｸM-PRO' 15 'Bold'; $QFont=MakeFont 'Comic Sans MS' 25 'Bold'; $Foot=MakeFont 'HG丸ｺﾞｼｯｸM-PRO' 19 'Bold'
