    2 { Header $g 'K-BEAUTY CLINIC CARD'; DrawRound $g 70 165 940 1088 42 (MakeBrush '#f3fbff') (MakePen '#9bd5e8' 6); DrawImg $g $Imgs[7].FullName 360 185 350 320 0; DrawText $g '肌管理カルテ' $Label (MakeBrush '#2b93b5') 110 470 860 45; Pair $g 560 'Q1' '美容の入口は？' @('つ','積み重ね') @('わ','渡韓アップデート') '#27a879' '#e94778'; Pair $g 795 'Q2' 'きれいの届け方は？' @('と','透明感') @('ぐ','グロウ') '#219fb0' '#6e63d8'; Pair $g 1030 'Q3' '求める気分は？' @('じ','自分軸') @('し','シェア提案') '#ff8a23' '#9b66de' }
    3 { Header $g 'PHOTO BOOTH'; for($i=0;$i -lt 4;$i++){ DrawRound $g (105+$i*220) 170 185 245 24 (MakeBrush '#ffffff') (MakePen '#f7aac0' 4); DrawImg $g $Imgs[$i].FullName (120+$i*220) 190 155 165 (($i%2)*8-4) }; DrawRound $g 92 460 896 770 36 (MakeBrush '#fff7fb') (MakePen '#f7aac0' 5); Pair $g 520 'Q1' '美容の入口は？' @('つ','積み重ね') @('わ','渡韓アップデート') '#27a879' '#e94778'; Pair $g 750 'Q2' 'きれいの届け方は？' @('と','透明感') @('ぐ','グロウ') '#219fb0' '#6e63d8'; Pair $g 980 'Q3' '求める気分は？' @('じ','自分軸') @('し','シェア提案') '#ff8a23' '#9b66de' }
    4 { Header $g 'K-POP STAGE'; DrawRound $g 80 180 920 1030 42 (MakeBrush '#fff0f6') (MakePen '#e94778' 5); for($i=0;$i -lt 8;$i++){DrawImg $g $Imgs[$i].FullName (65+$i*120) 210 120 150 (($i%3)-1)*7}; DrawText $g 'BEAUTY MOOD LIVE' (MakeFont 'Comic Sans MS' 34 'Bold') (MakeBrush '#e94778') 120 395 840 58; Pair $g 505 'Q1' '美容の入口は？' @('つ','積み重ね') @('わ','渡韓アップデート') '#27a879' '#e94778'; Pair $g 745 'Q2' 'きれいの届け方は？' @('と','透明感') @('ぐ','グロウ') '#219fb0' '#6e63d8'; Pair $g 985 'Q3' '求める気分は？' @('じ','自分軸') @('し','シェア提案') '#ff8a23' '#9b66de' }
    5 { Header $g 'K-COSME STORE'; DrawRound $g 70 165 940 1100 32 (MakeBrush '#fbfff2') (MakePen '#bdd98a' 5); for($r=0;$r -lt 3;$r++){ $y=315+$r*300; DrawRound $g 100 $y 880 145 20 (MakeBrush '#ffffff') (MakePen '#d5c08e' 4); DrawImg $g $Imgs[$r].FullName 130 ($y-65) 155 155 -3; DrawImg $g $Imgs[$r+4].FullName 790 ($y-65) 155 155 4 }; Pair $g 470 'Q1' '美容の入口は？' @('つ','積み重ね') @('わ','渡韓アップデート') '#27a879' '#e94778'; Pair $g 760 'Q2' 'きれいの届け方は？' @('と','透明感') @('ぐ','グロウ') '#219fb0' '#6e63d8'; Pair $g 1050 'Q3' '求める気分は？' @('じ','自分軸') @('し','シェア提案') '#ff8a23' '#9b66de' }
    6 { Header $g 'SEOUL METRO MAP'; for($i=0;$i -lt 3;$i++){ $pen=MakePen @('#27a879','#219fb0','#ff8a23')[$i] 9; $g.DrawBezier($pen,110,350+$i*230,350,260+$i*260,690,530+$i*180,970,410+$i*245); $pen.Dispose() }; for($i=0;$i -lt 6;$i++){DrawImg $g $Imgs[$i].FullName (90+$i*155) (195+($i%2)*60) 118 128 0}; Choice $g 120 450 330 84 'つ' '積み重ね' '#27a879' '#ffffff'; Choice $g 620 520 330 84 'わ' '渡韓アップデート' '#e94778' '#fff7fb'; Question $g 405 630 270 76 'Q1' '美容の入口は？' '#e94778'; Choice $g 120 755 330 84 'と' '透明感' '#219fb0' '#effcff'; Choice $g 620 825 330 84 'ぐ' 'グロウ' '#6e63d8' '#f4f1ff'; Question $g 405 935 270 76 'Q2' 'きれいの届け方は？' '#219fb0'; Choice $g 120 1060 330 84 'じ' '自分軸' '#ff8a23' '#fff6e8'; Choice $g 620 1130 330 84 'し' 'シェア提案' '#9b66de' '#fbf2ff'; Question $g 405 1240 270 76 'Q3' '求める気分は？' '#ff8a23' }
    7 { Header $g 'RECEIPT NOTE'; DrawRound $g 220 170 640 1080 16 (MakeBrush '#fffefa') (MakePen '#d8d0bf' 4); DrawText $g 'K-BEAUTY RECEIPT' (MakeFont 'Comic Sans MS' 31 'Bold') (MakeBrush '#3b2929') 250 205 580 50; for($i=0;$i -lt 4;$i++){DrawImg $g $Imgs[$i+2].FullName (95+$i*235) 310 145 145 (($i%2)*10-5)}; Pair $g 520 'Q1' '美容の入口は？' @('つ','積み重ね') @('わ','渡韓アップデート') '#27a879' '#e94778'; Pair $g 765 'Q2' 'きれいの届け方は？' @('と','透明感') @('ぐ','グロウ') '#219fb0' '#6e63d8'; Pair $g 1010 'Q3' '求める気分は？' @('じ','自分軸') @('し','シェア提案') '#ff8a23' '#9b66de' }
    8 { Header $g 'CUSHION COMPACT'; DrawImg $g $Imgs[0].FullName 360 175 360 310 0; for($i=0;$i -lt 6;$i++){ DrawRound $g (85+$i*155) 465 120 120 60 (MakeBrush '#fffdfb') (MakePen '#f3c9d5' 3) }; Pair $g 625 'Q1' '美容の入口は？' @('つ','積み重ね') @('わ','渡韓アップデート') '#27a879' '#e94778'; Pair $g 855 'Q2' 'きれいの届け方は？' @('と','透明感') @('ぐ','グロウ') '#219fb0' '#6e63d8'; Pair $g 1085 'Q3' '求める気分は？' @('じ','自分軸') @('し','シェア提案') '#ff8a23' '#9b66de' }
    9 { Header $g 'HONGDAE NEON'; $g.Clear([Drawing.ColorTranslator]::FromHtml('#fff0d8')); Header $g 'HONGDAE NEON'; DrawRound $g 95 170 890 1070 40 (MakeBrush '#2c2442') (MakePen '#ff8fbd' 5); DrawText $g 'K-BEAUTY NIGHT' (MakeFont 'Comic Sans MS' 36 'Bold') (MakeBrush '#ffe47a') 120 210 840 58; for($i=0;$i -lt 5;$i++){DrawImg $g $Imgs[$i].FullName (110+$i*175) 300 140 150 (($i%2)*8-4)}; Pair $g 520 'Q1' '美容の入口は？' @('つ','積み重ね') @('わ','渡韓アップデート') '#66e6b2' '#ff79ad'; Pair $g 755 'Q2' 'きれいの届け方は？' @('と','透明感') @('ぐ','グロウ') '#63e8ff' '#9e89ff'; Pair $g 990 'Q3' '求める気分は？' @('じ','自分軸') @('し','シェア提案') '#ffb34e' '#d5a0ff' }
    10 { Header $g 'MINI APP UI'; DrawRound $g 190 170 700 1080 48 (MakeBrush '#ffffff') (MakePen '#f2abc0' 5); DrawRound $g 235 220 610 90 45 (MakeBrush '#ffe9f0') $null; DrawText $g '오늘의 BEAUTY MOOD' (MakeFont 'Comic Sans MS' 30 'Bold') (MakeBrush '#e94778') 255 230 570 70; DrawImg $g $Imgs[6].FullName 385 330 310 270 0; Pair $g 610 'Q1' '美容の入口は？' @('つ','積み重ね') @('わ','渡韓アップデート') '#27a879' '#e94778'; Pair $g 830 'Q2' 'きれいの届け方は？' @('と','透明感') @('ぐ','グロウ') '#219fb0' '#6e63d8'; Pair $g 1050 'Q3' '求める気分は？' @('じ','自分軸') @('し','シェア提案') '#ff8a23' '#9b66de' }
  }
  Footer $g
  $file=Join-Path $OutDir ('beauty-mood-korean-{0:D2}-code.png' -f $v)
  $bmp.Save($file,[Drawing.Imaging.ImageFormat]::Png)
  $prompt="Use case: infographic-diagram. Asset type: TikTok vertical post. Korean K-beauty taste design version $v ($($Names[$v-1])). Title exactly ビューティムード診断. Cute Korean-style rounded typography, yellow-cream base, Mobby Toka beauty mascot characters. Show only 3 axes: Q1 美容の入口は？ choices つ 積み重ね and わ 渡韓アップデート; Q2 きれいの届け方は？ choices と 透明感 and ぐ グロウ; Q3 求める気分は？ choices じ 自分軸 and し シェア提案. No bottom 8-type result display, no Roman option letters, no fourth axis, no watermark."
